<?php $txns=$data['transactions'] ?? []; ?><div class="table-scroll"><table><thead><tr><th>Tanggal</th><th>No. Jurnal</th><th>Badan Usaha</th><th>Deskripsi</th><th>Akun</th><th>Nominal</th><th>Status</th><th>Control</th></tr></thead><tbody><?php foreach($txns as $t): ?><tr><td><?=e($t['date'])?></td><td><span class="mono"><?=e($t['no'])?></span></td><td><b><?=e($t['company'])?></b></td><td><?=e($t['desc'])?></td><td><?=e($t['account'])?></td><td class="amount <?=e($t['type'])?>"><?= $t['type']==='expense'?'-':'+' ?><?=money($t['amount'])?></td><td><span class="status ok">● <?=e($t['status'])?></span></td><td><?php if(roleCan($data['current_user']['role'],'journal.reverse')):?><button class="mini-btn" onclick="reverseJournal(<?=$t['id']?>)">Reverse</button><?php else:?><span class="muted-copy">—</span><?php endif?></td></tr><?php endforeach ?></tbody></table></div>